import 'package:flutter/material.dart';import 'package:platform_core_frontend/features/super_admin/data/super_admin_repository.dart';import 'package:platform_core_frontend/features/super_admin/models/admin_masjid_model.dart';import 'package:platform_core_frontend/features/super_admin/presentation/widgets_common.dart';import 'package:platform_core_frontend/shared/widgets/loading_view.dart';
class AdminMasjidDetailScreen extends StatelessWidget{const AdminMasjidDetailScreen({super.key,required this.id,this.initial});final String id;final AdminMasjidModel? initial;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Masjid Details')),body:FutureBuilder(future:SuperAdminRepository().getMasjid(id),initialData:initial,builder:(c,s){if(!s.hasData)return const LoadingView();final m=s.data!;return ListView(padding:const EdgeInsets.all(16),children:[AdminStatusChip(m.status),InfoRow('Name',m.name),InfoRow('Country',m.country),InfoRow('State',m.state),InfoRow('Address',m.address),InfoRow('Contact',m.contactNo),InfoRow('Requester',m.requestedByName),InfoRow('Requester Phone',m.requestedByPhone),InfoRow('Requester Email',m.requestedByEmail),InfoRow('Imam',m.imamName),InfoRow('Users',m.usersCount),InfoRow('Welcome Message',m.welcomeMsg),InfoRow('Description',m.description),InfoRow('Created',m.createdAt)]);}));}
